public class Rechenzentrale {

    interface Operation {
        int anwenden(int a, int b);
    }

    public static void rechnen(int a, int b, Operation op) {
        System.out.println("Ergebnis: " + op.anwenden(a, b));
    }

    public static void main(String[] args) {
        rechnen(10, 4, (a, b) -> a + b);
        rechnen(10, 4, (a, b) -> a * b);
        rechnen(10, 4, (a, b) -> a - b);
    }
}

