public class Textfilter {

    interface Pruefer {
        boolean pruefe(String text);
    }

    public static void pruefe(String text, Pruefer pruefer) {
        System.out.println(pruefer.pruefe(text));
    }

    public static void main(String[] args) {
        System.out.println("Lang genug:");
        pruefe("Banane", t -> t.length() > 5);
        System.out.println("Enthält a:");
        pruefe("Banane", t -> t.contains("a"));
    }
}
